Future<Uint8List> convertCameraImageToPng(CameraImage image) {
  // Create an RGB image with the same dimensions
  final convertedImage = Image(image.width, image.height, numChannels: 3);

  final yPlane = image.planes[0];
  final uPlane = image.planes[1];
  final vPlane = image.planes[2];

  for (int y = 0; y < image.height; y++) {
    for (int x = 0; x < image.width; x++) {
      // Y channel (luma)
      final yIndex = (y * yPlane.bytesPerRow) + x;
      final Y = yPlane.bytes[yIndex];

      // U and V channels (chroma)
      final uvY = y ~/ 2;
      final uvX = x ~/ 2;
      final uIndex = (uvY * uPlane.bytesPerRow) + uvX;
      final vIndex = (uvY * vPlane.bytesPerRow) + uvX;

      final U = uPlane.bytes[uIndex] - 128;
      final V = vPlane.bytes[vIndex] - 128;

      // Convert YUV to RGB
      int r = (Y + 1.402 * V).round();
      int g = (Y - 0.34414 * U - 0.71414 * V).round();
      int b = (Y + 1.772 * U).round();

      r = r.clamp(0, 255);
      g = g.clamp(0, 255);
      b = b.clamp(0, 255);

      convertedImage.setPixelRgb(x, y, r, g, b);
    }
  }

  return encodePng(convertedImage);
}

